import {mapFromInterior,stampInterior,templateFromMap,interiorAssets} from './interior-model.js';
import {movementAt} from './world-model.js';

export function interiorWorkshop(api){
  const $=s=>document.querySelector(s),esc=api.esc,state={id:null,query:'',category:'all',limit:24};
  const list=()=>api.library.list('interiorTemplates',api.project());
  function choose(t){state.id=t.id;api.mode('interior');api.collapse();api.toast('Tap the top-left tile to stamp '+t.name+'.');}
  function render(target){
    const all=list(),categories=[...new Set(all.map(t=>t.category||'Interiors'))].sort();
    target.innerHTML=`<div class="toolbox-search"><input id="interiorSearch" type="search" aria-label="Search interiors" placeholder="House, Centre, Celadon, Silph, lab…" value="${esc(state.query)}"><select id="interiorCategory" aria-label="Interior category"><option value="all">All interiors</option><option value="mine" ${state.category==='mine'?'selected':''}>My interiors</option>${categories.map(c=>`<option value="${esc(c)}" ${state.category===c?'selected':''}>${esc(c)}</option>`).join('')}</select></div><p class="hint-line">Create a furnished map or stamp a whole room. Tiles and extracted furniture stay editable.</p><div id="interiorCards" class="toolbox-cards"></div><button id="moreInteriors" type="button" class="full" hidden>Show more interiors</button><button id="saveInteriorTemplate" type="button" class="full">Save current map as an interior</button>`;
    const cards=()=>{const q=state.query.toLowerCase(),found=all.filter(t=>(state.category==='all'||t.category===state.category||state.category==='mine'&&api.library.has('interiorTemplates',t.id))&&(t.name+' '+t.category+' '+(t.tags||'')).toLowerCase().includes(q));$('#interiorCards').innerHTML=found.slice(0,state.limit).map(t=>`<article class="toolbox-card">${t.preview?`<img loading="lazy" class="toolbox-thumb interior-preview" src="${esc(t.preview)}" alt="${esc(t.name)}">`:'<span class="interior-placeholder">▦</span>'}<b>${esc(t.name)}</b><small>${t.width} × ${t.height} tiles</small><div class="toolbox-actions"><button data-new-interior="${esc(t.id)}" type="button">New map</button><button data-stamp-interior="${esc(t.id)}" type="button">Stamp</button>${t.containedPrefabIds?.length?`<button data-interior-items="${esc(t.id)}" type="button">Items</button>`:''}${api.library.has('interiorTemplates',t.id)?`<button data-delete-interior="${esc(t.id)}" type="button" aria-label="Remove saved interior">Remove</button>`:''}</div></article>`).join('')||'<p class="empty">No matching interiors.</p>';$('#moreInteriors').hidden=found.length<=state.limit;target.querySelectorAll('[data-new-interior]').forEach(b=>b.onclick=()=>create(all.find(t=>t.id===b.dataset.newInterior)));target.querySelectorAll('[data-stamp-interior]').forEach(b=>b.onclick=()=>choose(all.find(t=>t.id===b.dataset.stampInterior)));target.querySelectorAll('[data-interior-items]').forEach(b=>b.onclick=()=>api.objectsFor(all.find(t=>t.id===b.dataset.interiorItems)));target.querySelectorAll('[data-delete-interior]').forEach(b=>b.onclick=()=>{const t=all.find(t=>t.id===b.dataset.deleteInterior);api.modal('Remove saved interior',`<p>Remove ${esc(t.name)} from your reusable interiors? Maps already created from it stay intact.</p>`,async()=>{await api.library.remove('interiorTemplates',t.id);api.refresh();},'Remove');});};
    $('#interiorSearch').oninput=e=>{state.query=e.target.value;state.limit=24;cards();};$('#interiorCategory').onchange=e=>{state.category=e.target.value;state.limit=24;cards();};$('#moreInteriors').onclick=()=>{state.limit+=24;cards();};$('#saveInteriorTemplate').onclick=saveCurrent;cards();
  }
  function create(t){api.modal('Create '+t.name,`${t.preview?`<img class="interior-dialog-preview" src="${esc(t.preview)}" alt="Interior layout">`:''}<label>Map name<input id="newInteriorName" value="${esc(t.name)}" maxlength="120"></label><p>${t.width} × ${t.height} tiles · editable room layout and walking rules.</p><label class="check"><input id="linkNewInterior" type="checkbox" checked> Link an entrance from the current map</label><p class="hint-line">Choose the entrance on your outdoor map next. This interior’s arrival tile is already marked.</p>`,()=>{
      const p=api.project();if(p.maps.length>=80||p.maps.reduce((n,m)=>n+m.width*m.height,0)+t.width*t.height>400000)throw Error('This room exceeds the project map / tile limit.');
      const fromMap=api.map(),link=$('#linkNewInterior').checked,map=mapFromInterior(t,$('#newInteriorName').value.trim()||t.name),session=api.session();
      map.world={x:fromMap.world.x+280,y:fromMap.world.y};map.rom={generated:true,sourceId:session?.id||fromMap.rom?.sourceId||null,interiorKind:t.kind||'house',mapType:8,originalWidth:0,originalHeight:0,originalBlocks:[],...(session?.reader.code===t.sourceCode&&session.reader.byKey(t.sourceKey)?{templateKey:t.sourceKey}:{})};
      api.change(()=>{api.library.attach(p,'interiorTemplates',t);p.maps.push(map);});api.close();
      if(link){api.loadMap(fromMap.id);api.links().begin({arrival:{mapId:map.id,...t.entry},label:t.name+' entrance'});}else api.loadMap(map.id);
      api.collapse();api.refresh();return false;
    },'Create interior');}
  function tap(x,y){const t=list().find(t=>t.id===state.id);if(!t){api.toast('Choose an interior in Objects → Interiors.');return;}if(x+t.width>api.map().width||y+t.height>api.map().height){api.toast('This '+t.width+' × '+t.height+' room needs more space. Use Crop / resize or create a new map.');return;}
    api.modal('Stamp '+t.name,`<p>Place the ${t.width} × ${t.height} room at tile ${x}, ${y}. Tiles and walking rules in this rectangle will be replaced.</p><label class="check"><input id="interiorReplaceObjects" type="checkbox" checked> Replace furniture in this rectangle</label><p>Existing NPCs, events and connections are retained. Undo restores the previous room.</p>`,()=>{api.change(()=>{api.library.attach(api.project(),'interiorTemplates',t);stampInterior(api.map(),t,x,y,{replaceObjects:$('#interiorReplaceObjects').checked});});api.refresh();api.toast('Interior stamped. Tiles and furniture can be edited.');},'Stamp interior');
  }
  function saveCurrent(){const map=api.map();let entry=map.generator?.entrance;for(let y=map.height-1;y>=0&&!entry;y--)for(let x=0;x<map.width;x++)if(!movementAt(map,x,y).collision){entry={x,y};break;}if(!entry){api.toast('Make at least one walkable tile before saving this room.');return;}
    api.modal('Save reusable interior',`<label>Name<input id="saveInteriorName" maxlength="120" value="${esc(map.name)}"></label><label>Category<input id="saveInteriorCategory" maxlength="60" value="My interiors"></label><div class="field-row"><label>Entrance X<input id="saveInteriorX" type="number" min="0" max="${map.width-1}" value="${entry.x}"></label><label>Entrance Y<input id="saveInteriorY" type="number" min="0" max="${map.height-1}" value="${entry.y}"></label></div><p>Stores the editable layout, furniture and walking rules across projects. NPCs, scripts, portals and story flags stay with the original map.</p>`,async()=>{const entry={x:+$('#saveInteriorX').value,y:+$('#saveInteriorY').value};if(![entry.x,entry.y].every(Number.isInteger)||entry.x<0||entry.y<0||entry.x>=map.width||entry.y>=map.height||movementAt(map,entry.x,entry.y).collision)throw Error('Choose a walkable entrance tile inside this map.');const t=templateFromMap(map,{name:$('#saveInteriorName').value.trim()||map.name,category:$('#saveInteriorCategory').value.trim()||'My interiors',entry});t.preview=await api.preview(map);await api.library.save('interiorTemplates',t,api.asset);api.change(()=>api.library.attach(api.project(),'interiorTemplates',t));api.refresh();api.toast('Interior saved across projects.');},'Save interior');
  }
  return{state,list,render,choose,create,tap,saveCurrent};
}
